// Title: Automatically delete a PNG worksheet image generated by Aspose.Cells after 24 hours using an async background task in C#
// AI Prompts: Generate C# code that uses Aspose.Cells to render a worksheet to a PNG file and then starts an asynchronous task that waits 24 hours before deleting the file. | Create a reusable method that accepts a Worksheet and a TimeSpan, saves the worksheet as a PNG with ImageOrPrintOptions, and schedules the file for removal after the given interval. | Add cancellation token support to the delayed deletion routine so the PNG can be removed earlier if the token is triggered.
// Common Searches: how to schedule automatic deletion of Aspose.Cells generated PNG after one day in .NET | C# async task to delete temporary Excel worksheet image after 24 hours | Aspose.Cells render worksheet to PNG and clean up file after delay
// Tags: Aspose.Cells PNG export of worksheet | async delayed file deletion C# | ImageOrPrintOptions one page per sheet | background task for temporary file expiration | cleanup of generated Excel image

using System;
using System.IO;
using System.Threading.Tasks;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// // Demonstrates creating a workbook, rendering the first worksheet to a PNG file in the temp folder, and launching an asynchronous Task that waits 24 hours before deleting the image.
class Program
{
    static async Task Main()
    {
        try
        {
            // Create a new workbook (default empty workbook)
            Workbook workbook = new Workbook();

            // Add sample data to the first worksheet
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Hello Aspose.Cells!");

            // Define the PNG file path in the temporary folder
            string pngPath = Path.Combine(Path.GetTempPath(), "WorksheetImage.png");

            // Set image rendering options (default format is PNG)
            ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
            {
                OnePagePerSheet = true
            };

            // Render the first worksheet to a PNG image
            SheetRender renderer = new SheetRender(sheet, imgOptions);
            renderer.ToImage(0, pngPath);

            Console.WriteLine($"Worksheet image saved to: {pngPath}");

            // Schedule automatic deletion after 24 hours (runs in background)
            _ = DeleteFileAfterDelayAsync(pngPath, TimeSpan.FromHours(24));
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
        }

        // Keep the console open for demonstration purposes
        Console.WriteLine("Press any key to exit...");
        Console.ReadKey();
    }

    // Background job that waits for the specified delay then deletes the file
    private static async Task DeleteFileAfterDelayAsync(string filePath, TimeSpan delay)
    {
        try
        {
            await Task.Delay(delay);

            if (File.Exists(filePath))
            {
                File.Delete(filePath);
                Console.WriteLine($"Deleted file after {delay.TotalHours} hours: {filePath}");
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error deleting file: {ex.Message}");
        }
    }
}
